command:
printf %s 'charon {
 install_routes = no
 load_modular = yes
 plugins {
 include strongswan.d/charon/*.conf
 }
}
include strongswan.d/*.conf
' > /usr/local/etc/strongswan.conf

records.stdout:
connections {
 msc {
  version = 2
  local_addrs = 10.200.1.2
  remote_addrs = 10.100.1.2
  proposals = aes256gcm16-prfsha384-ecp384
  reauth_time = 3h
  rekey_time = 0s
  over_time = 10m
  dpd_delay = 10s
  keyingtries = 0
  mobike = no
  local {
   auth = ecdsa-384-sha384
   certs = cert.pem
   id = ND_I_B1.msc.test
  }
  remote {
   auth = ecdsa-384-sha384
   id = ND_I_A1.msc.test
   cacerts = ca.pem
   revocation = strict
  }
  children {
   protected {
    local_ts = 10.2.1.0/24
    remote_ts = 10.1.1.0/24
    mode = tunnel
    reqid = 101
    esp_proposals = aes256gcm16-ecp384
    rekey_time = 50m
    life_time = 1h
    start_action = trap
    dpd_action = trap
    close_action = trap
   }
  }
 }
}
